Given an integer array arr[], find the sum of any two elements whose sum is closest to zero. Note: In case if we have two ways to form sum closest to zero, return the maximum sum among them.Examples:Input: arr[] = [-8, 5, 2, -6]Output: -1Explanation: The min absolute sum pair is (5, -6)Input:  arr[] = [0, -8, -6, 3]Output: 3Explanation: We have a tie between (0, 3) and (-6, 3). We pick the max sum in this case which is 0+3Input: arr[] = [-7, 4, 1, -2]Output: -1Explanation: The min absolute sum pair is (1, -2).Try It YourselfTable of Content[Naive Approach] Check Every Possible Pair - O(n^2) Time and O(1) Space[Better Approach] Using Sorting + Binary Search - O(nlog(n)) Time and O(1) Space[Expected Approach] Using Sorting + Two Pointer - O(nlog(n)) Time and O(1) Space[Naive Approach] Check Every Possible Pair - O(n^2) Time and O(1) SpaceThe idea is to use the naive method that checks the sum of every possible pair of elements in the array and keeps track of the pair with the minimum absolute sum.
            C++

    #include <bits/stdc++.h>
using namespace std;

int closestToZero(vector<int>& arr) {

    // Initialize result with sum of first two elements
    int res = arr[0] + arr[1];

    // Check all pairs
    for (int i = 0; i < arr.size() - 1; i++) {
        for (int j = i + 1; j < arr.size(); j++) {
            int sum = arr[i] + arr[j];

            if (abs(sum) < abs(res)) {
                res = sum;
            }
            else if (abs(sum) == abs(res)) {
                res = max(res, sum);
            }
        }
    }
    return res;
}

int main() {
    vector<int> arr = {0, -8, -6, 3};
    cout << closestToZero(arr);
    return 0;
}


